// Golden vectors generated by running the UPSTREAM Kotlin QrData.kt (OpenCfMoto Android) on a JVM
// over a corpus of spec vectors and edge cases. The corpus avoids inputs where desktop Java differs
// from Android (ICU regex / strict URLDecoder hex check), so these are Android-exact.

import XCTest
@testable import OpenCfMotoCore

final class QRGoldenTests: XCTestCase {

    func testParseMatchesKotlinGolden() {
        for g in Self.qrGolden {
            let q = BikeQR.parse(g.raw)
            let ctx = "raw=\(g.raw.debugDescription)"
            XCTAssertEqual(q?.ssid, g.ssid, ctx)
            XCTAssertEqual(q?.password, g.pwd, ctx)
            XCTAssertEqual(q?.auth, g.auth, ctx)
            XCTAssertEqual(q?.mac, g.mac, ctx)
            XCTAssertEqual(q?.name, g.name, ctx)
            XCTAssertEqual(q?.action, g.action, ctx)
            XCTAssertEqual(q?.modelId, g.modelId, ctx)
            XCTAssertEqual(q?.sn, g.sn, ctx)
            XCTAssertEqual(q?.channel, g.channel, ctx)
            if q == nil {
                XCTAssertEqual(BikeQR.failureHint(for: g.raw), g.hint, ctx)
            }
            XCTAssertEqual(BikeScope.id(forRaw: AppJvmText.trim(g.raw)), g.bikeId, ctx)
        }
    }

    func testManualMatchesKotlinGolden() {
        for g in Self.manualGolden {
            XCTAssertEqual(BikeQR.manualPairingURL(ssid: g.ssid, password: g.pwd, displayName: g.name), g.raw,
                           "ssid=\(g.ssid.debugDescription) pwd=\(g.pwd.debugDescription)")
            if let raw = g.raw { XCTAssertEqual(BikeQR.buildManual(ssid: g.ssid, password: g.pwd, displayName: g.name)?.raw, raw) }
        }
    }
}

